import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CTeY_0bQ.js";const _=JSON.parse('{"title":"0003 适配器只在安装时生成一次并锁定","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0003-generate-once-then-lock.md","filePath":"reference/adr/0003-generate-once-then-lock.md","lastUpdated":null}'),i={name:"reference/adr/0003-generate-once-then-lock.md"};function n(l,e,s,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<div><h1 id="_0003-适配器只在安装时生成一次并锁定" tabindex="-1">0003 适配器只在安装时生成一次并锁定 <a class="header-anchor" href="#_0003-适配器只在安装时生成一次并锁定" aria-label="Permalink to &quot;0003 适配器只在安装时生成一次并锁定&quot;">​</a></h1><ul><li>状态：提议</li><li>详见：<a href="https://github.com/yiyisf/laoshi/blob/main/docs/design/init-bootstrap.md" target="_blank" rel="noreferrer">init-bootstrap.md</a></li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>&quot;让核心能力根据所处平台自己长出来&quot;有价值：新平台接入成本低。但如果每次运行都由模型现场决定如何调用平台，流程就不再可控、不可复现，和本项目&quot;AI 和人都不即兴发挥&quot;的目标冲突。内网模型能力也较弱，现场生成风险更高。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li>适配器由内置 skill <strong>在安装时</strong>借助 LLM 探测与生成，经人确认后<strong>锁定</strong>（<code>laoshi.adapter.lock.json</code>：平台版本、laoshi 版本、生成物哈希、探针结果、确认记录）。</li><li>运行时只执行锁定版本；<code>doctor</code> 校验哈希，平台或 laoshi 版本变化时标记过期。</li><li>优先生成<strong>声明式适配器描述</strong>（数据），由通用解释器执行；描述表达不了时才生成代码，并要求更严格的审阅。</li><li>能力有没有，以<strong>探针测试</strong>的真实结果为准，不以模型的判断为准。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>需要先写探针集和描述解释器；内部平台的真实接口形态决定声明式方案是否够用。</li><li>生成物视同代码，必须经人确认；锁定文件放机器配置目录，不放项目仓库。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/docs/adr/0003-generate-once-then-lock.md">docs/adr/0003-generate-once-then-lock.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/docs/adr/0003-generate-once-then-lock.md">在 GitHub 上编辑</a></p>',2)])])}const m=a(i,[["render",n]]);export{_ as __pageData,m as default};
